import{_ as t,o,c as a,a5 as r}from"./chunks/framework.BfQ7H7Qx.js";const g=JSON.parse('{"title":"Plan — FR 3.6.12: Add Material Repository","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/05-content-task-workflow/3-6-12-add-material-repository/plan.md","filePath":"feature/srs/05-content-task-workflow/3-6-12-add-material-repository/plan.md"}'),d={name:"feature/srs/05-content-task-workflow/3-6-12-add-material-repository/plan.md"};function c(i,e,s,l,n,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <a href="./spec.html">Spec</a> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="plan-—-fr-3-6-12-add-material-repository" tabindex="-1">Plan — FR 3.6.12: Add Material Repository <a class="header-anchor" href="#plan-—-fr-3-6-12-add-material-repository" aria-label="Permalink to &quot;Plan — FR 3.6.12: Add Material Repository&quot;">​</a></h1><p>&gt; Implements <a href="./spec.html">spec.md</a> for canonical roles <code>Owner, Manager, Creator, Client</code> enforcing <code>BR-36</code>.</p><h2 id="_1-technical-component-map" tabindex="-1">1. Technical Component Map <a class="header-anchor" href="#_1-technical-component-map" aria-label="Permalink to &quot;1. Technical Component Map&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Layer</th><th style="text-align:left;">Repository / Package</th><th style="text-align:left;">Concrete Classes &amp; Files</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>API Gateway</strong></td><td style="text-align:left;"><code>brandhub-api-gateway</code></td><td style="text-align:left;"><code>GatewayConfig.java</code> (<code>/api/v1/**</code>, <code>/ws/**</code>, public <code>/api/v1/public/surveys/**</code>), <code>JwtAuthFilterGatewayFilterFactory.java</code></td></tr><tr><td style="text-align:left;"><strong>Controllers</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>MaterialController.uploadMaterial() / createUploadSession() / createMultipartUploadSession() / nextUploadParts() / confirmUploadSession() / cancelUploadSession(), MaterialFolderController.create(), RepositoryEncryptedMediaController.upload(), ClientVaultController.folder() / share()</code></td></tr><tr><td style="text-align:left;"><strong>Services</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>MaterialUploadCoordinator, MaterialUploadPolicy, MaterialContentValidator, RepositoryEnvelopeCrypto, StorageQuotaService, MaterialFolderService, MaterialVersionService, ClientVaultService</code></td></tr><tr><td style="text-align:left;"><strong>Repositories / Stores</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;">MaterialMongoRepository, MaterialSessionStore, StorageQuotaService</td></tr><tr><td style="text-align:left;"><strong>Security / ACL</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>RequireRoleAspect.java</code>, <code>WorkspaceAccessService.java</code>, <code>MaterialAccessPolicy.java</code>, <code>ChatInboundChannelInterceptor.java</code></td></tr><tr><td style="text-align:left;"><strong>Web Frontend</strong></td><td style="text-align:left;"><code>brandhub-web</code></td><td style="text-align:left;"><code>src/pages/library/components/{MediaUploadButton,MaterialUploadForm,MaterialUploadFields,MaterialAudienceFields,MaterialFolderPicker,DuplicateResolutionModal}.tsx</code>, <code>src/services/materialService.ts</code></td></tr><tr><td style="text-align:left;"><strong>Mobile App</strong></td><td style="text-align:left;"><code>brandhub-mobile-app</code></td><td style="text-align:left;"><code>src/screens/content/{UploadScreen,TaskUploadScreen,CameraRecordScreen}.tsx</code>, <code>src/screens/more/MediaLibraryScreen.tsx</code>, <code>src/services/uploadService.ts</code></td></tr></tbody></table><h2 id="_2-persistence-storage-indexing-architecture" tabindex="-1">2. Persistence, Storage &amp; Indexing Architecture <a class="header-anchor" href="#_2-persistence-storage-indexing-architecture" aria-label="Permalink to &quot;2. Persistence, Storage &amp; Indexing Architecture&quot;">​</a></h2><ul><li><strong>Primary Data Stores:</strong> MongoDB <code>materials</code> (<code>sha256</code>, <code>folderId</code>, <code>versionNumber</code>, <code>encryptionMetadata</code>, <code>visibility</code>, <code>clientProfileId</code>), <code>material_folders</code>, <code>material_versions</code>, <code>client_vault_shares</code>; AWS S3 (<code>SYSTEM_S3</code>).</li><li><strong>Consolidated Technical Design:</strong><ul><li>Folds in <code>add-material-repository</code>, <code>pre-s3-encryption</code>, <code>mp4-upload-detection</code>, <code>s3-folder-vault-security</code>, and <code>client-folder-sharing</code>: validates magic-byte signatures (including ISO-BMFF <code>ftyp</code> box inspection for <code>.mp4</code>/<code>.mov</code> video detection), enforces the 5 GB free S3 quota + monthly storage add-on limits (<code>StorageQuotaService</code>), encrypts payloads with per-object AES-256-GCM DEKs wrapped before S3 storage (<code>RepositoryEnvelopeCrypto</code>), creates nested folders, detects SHA-256 content / same-folder filename collisions (<code>Skip</code> / <code>Keep Both</code> / <code>Overwrite as v2..vN</code>), auto-tags <code>Client</code> uploads as <code>BRAND_REFERENCE</code> scoped to <code>clientProfileId</code>, and supports sharing <code>Client</code> Personal Vault folders across Workspaces without duplicating S3 bytes.</li><li><strong>Index &amp; Query Discipline:</strong> All MongoDB (<code>tasks</code>, <code>task_sections</code>, <code>task_comments</code>, <code>materials</code>, <code>material_folders</code>, <code>surveys</code>, <code>chat_messages</code>) and PostgreSQL (<code>hashtags</code>, <code>task_content_snapshots</code>, <code>audit_logs</code>) queries include <code>workspaceId</code> (<code>workspace_id</code>) as the leading filter predicate with stable <code>(timestamp, _id)</code> cursor/page tie-breakers.</li><li><strong>Storage &amp; Encryption Hygiene:</strong> Binary uploads validate MIME + magic bytes up front, enforce quota/size ceilings, and stream through private capability or presigned endpoints rather than exposing raw bucket keys.</li></ul></li></ul><h2 id="_3-end-to-end-execution-flow" tabindex="-1">3. End-to-End Execution Flow <a class="header-anchor" href="#_3-end-to-end-execution-flow" aria-label="Permalink to &quot;3. End-to-End Execution Flow&quot;">​</a></h2><ol><li><strong>User Action:</strong> Authenticated actor (<code>Owner, Manager, Creator, Client</code>) invokes <strong>Add Material Repository</strong> via <code>src/pages/library/components/{MediaUploadButton,MaterialUploadForm,MaterialUploadFields,MaterialAudienceFields,MaterialFolderPicker,DuplicateResolutionModal}.tsx</code>, <code>src/services/materialService.ts</code> (Web) or <code>src/screens/content/{UploadScreen,TaskUploadScreen,CameraRecordScreen}.tsx</code>, <code>src/screens/more/MediaLibraryScreen.tsx</code>, <code>src/services/uploadService.ts</code> (Mobile).</li><li><strong>Edge &amp; Tenant Verification:</strong> <code>brandhub-api-gateway</code> validates JWT (or STOMP <code>CONNECT</code> Bearer header); <code>brandhub-business-service</code> verifies live PostgreSQL Workspace membership and object-level ACL (<code>Owner, Manager, Creator, Client</code>).</li><li><strong>Domain Policy &amp; Validation:</strong> <code>MaterialUploadCoordinator, MaterialUploadPolicy, MaterialContentValidator, RepositoryEnvelopeCrypto, StorageQuotaService, MaterialFolderService, MaterialVersionService, ClientVaultService</code> validates payload constraints, <code>BR-36</code> business rules, revision/lease concurrency tokens, and quota/reference guards, mapping violations to <code>400 INVALID_FILE_TYPE</code> / <code>FILENAME_INVALID</code>, <code>403 FORBIDDEN</code>, <code>409 DUPLICATE_MATERIAL_DETECTED</code>, <code>413 FILE_TOO_LARGE</code> / <code>STORAGE_QUOTA_EXCEEDED</code> (<code>BR-36</code>).</li><li><strong>Atomic Persistence &amp; Outbox Side Effects:</strong> Commits state updates to MongoDB <code>materials</code> (<code>sha256</code>, <code>folderId</code>, <code>versionNumber</code>, <code>encryptionMetadata</code>, <code>visibility</code>, <code>clientProfileId</code>), <code>material_folders</code>, <code>material_versions</code>, <code>client_vault_shares</code>; AWS S3 (<code>SYSTEM_S3</code>) and enqueues asynchronous notifications/workers (<code>task_notification_outbox</code>, <code>DriveFolderImportService</code>, <code>GoogleSheetsService</code>, or STOMP topic broadcast) after durable persistence.</li><li><strong>Client Cache &amp; Realtime Update:</strong> Frontend reconciles TanStack Query / Zustand / WebSocket state, preserves unsaved form drafts on conflict, and displays localized (<code>library.upload.* / library.folders.* / library.duplicate.*</code>) status feedback.</li></ol><h2 id="_4-security-concurrency-operational-resilience" tabindex="-1">4. Security, Concurrency &amp; Operational Resilience <a class="header-anchor" href="#_4-security-concurrency-operational-resilience" aria-label="Permalink to &quot;4. Security, Concurrency &amp; Operational Resilience&quot;">​</a></h2><ul><li><strong>Strict Multi-Tenant &amp; Per-Client Isolation:</strong> <code>WorkspaceAccessService</code> and <code>MaterialAccessPolicy</code> re-verify active membership on every request; <code>Client</code> queries are additionally restricted to their own <code>clientProfileId</code> where audience-scoped.</li><li><strong>Optimistic Concurrency &amp; Idempotency:</strong> CAS revision counters, unique <code>(workspaceId, senderUserId, clientMessageId)</code> indexes, and <code>DriveOperationLease</code> locks prevent duplicate side effects under network retries or multi-tab edits.</li><li><strong>Graceful Degradation:</strong> External provider hiccups (Google Drive, Google Sheets, AI moderation) return explicit retryable error codes without corrupting local MongoDB/PostgreSQL state.</li></ul><h2 id="_5-cross-references" tabindex="-1">5. Cross-References <a class="header-anchor" href="#_5-cross-references" aria-label="Permalink to &quot;5. Cross-References&quot;">​</a></h2><ul><li><strong>Lifecycle Artefacts:</strong> <a href="./spec.html">spec.md</a> · <a href="./task.html">task.md</a> · <a href="./test.html">test.md</a></li><li><strong>BA &amp; Module References:</strong> <a href="./../../../../ba/05-content-task-workflow.html">05-content-task-workflow.md</a> · <a href="./../../../../ba/12-state-machines.html">12-state-machines.md</a> · <a href="./../../../modules/README.html">Module Specs Index</a></li></ul><h2 id="endpoint-authorization-error-mapping-matrix" tabindex="-1">Endpoint, Authorization &amp; Error Mapping Matrix <a class="header-anchor" href="#endpoint-authorization-error-mapping-matrix" aria-label="Permalink to &quot;Endpoint, Authorization &amp; Error Mapping Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Aspect</th><th style="text-align:left;">Specification</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR / Feature</strong></td><td style="text-align:left;"><code>FR 3.6.12</code> — Add Material Repository</td></tr><tr><td style="text-align:left;"><strong>HTTP / WS Endpoints</strong></td><td style="text-align:left;"><code>POST /api/v1/workspaces/{workspaceId}/materials · POST /upload-session · POST /upload-session/multipart · POST /upload-session/{sessionId}/parts · POST /upload-session/confirm · DELETE /upload-session/{sessionId} · POST /folders · PUT /api/v1/repository-media · POST /api/v1/client-vault/folders · POST /api/v1/workspaces/{workspaceId}/client-vault/shares</code></td></tr><tr><td style="text-align:left;"><strong>Authorized Canonical Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator, Client</code></td></tr><tr><td style="text-align:left;"><strong>Controller -&gt; Service</strong></td><td style="text-align:left;"><code>MaterialController.uploadMaterial() / createUploadSession() / createMultipartUploadSession() / nextUploadParts() / confirmUploadSession() / cancelUploadSession(), MaterialFolderController.create(), RepositoryEncryptedMediaController.upload(), ClientVaultController.folder() / share()</code> -&gt; <code>MaterialUploadCoordinator, MaterialUploadPolicy, MaterialContentValidator, RepositoryEnvelopeCrypto, StorageQuotaService, MaterialFolderService, MaterialVersionService, ClientVaultService</code></td></tr><tr><td style="text-align:left;"><strong>Persistence / Cache Targets</strong></td><td style="text-align:left;">MongoDB <code>materials</code> (<code>sha256</code>, <code>folderId</code>, <code>versionNumber</code>, <code>encryptionMetadata</code>, <code>visibility</code>, <code>clientProfileId</code>), <code>material_folders</code>, <code>material_versions</code>, <code>client_vault_shares</code>; AWS S3 (<code>SYSTEM_S3</code>)</td></tr><tr><td style="text-align:left;"><strong>Business Rule Invariants</strong></td><td style="text-align:left;"><code>BR-36</code></td></tr><tr><td style="text-align:left;"><strong>Error Code Contract</strong></td><td style="text-align:left;"><code>400 INVALID_FILE_TYPE</code> / <code>FILENAME_INVALID</code>, <code>403 FORBIDDEN</code>, <code>409 DUPLICATE_MATERIAL_DETECTED</code>, <code>413 FILE_TOO_LARGE</code> / <code>STORAGE_QUOTA_EXCEEDED</code> (<code>BR-36</code>)</td></tr></tbody></table><h2 id="frontend-cache-i18n-theme-architecture" tabindex="-1">Frontend Cache, i18n &amp; Theme Architecture <a class="header-anchor" href="#frontend-cache-i18n-theme-architecture" aria-label="Permalink to &quot;Frontend Cache, i18n &amp; Theme Architecture&quot;">​</a></h2><ul><li><strong>Web State &amp; Query Management (<code>brandhub-web</code>):</strong><ul><li>Components &amp; Hooks: <code>src/pages/library/components/{MediaUploadButton,MaterialUploadForm,MaterialUploadFields,MaterialAudienceFields,MaterialFolderPicker,DuplicateResolutionModal}.tsx</code>, <code>src/services/materialService.ts</code>.</li><li>Query Keys &amp; Cache Invalidation: Scoped by authenticated <code>userId</code>, <code>agencyId</code>, or <code>workspaceId</code> so switching tenants or logging out never leaks cached records across boundaries.</li><li>Conflict &amp; Error Recovery: Preserves in-progress user form state on <code>400</code>/<code>409</code> responses, disables duplicate in-flight submissions, and never falls back to hardcoded mock data.</li></ul></li><li><strong>Mobile Parity (<code>brandhub-mobile-app</code>):</strong><ul><li>Screens &amp; Services: <code>src/screens/content/{UploadScreen,TaskUploadScreen,CameraRecordScreen}.tsx</code>, <code>src/screens/more/MediaLibraryScreen.tsx</code>, <code>src/services/uploadService.ts</code>.</li><li>Uses shared REST/WS contract, <code>expo-secure-store</code> Bearer token injection, and mobile <code>workspaceStore</code> / <code>authStore</code> synchronization.</li></ul></li><li><strong>Localization &amp; Theme Standards:</strong><ul><li>Key-parallel Vietnamese (<code>vi</code>) and English (<code>en</code>) locale entries under <code>library.upload.* / library.folders.* / library.duplicate.*</code> with zero hardcoded strings.</li><li>Semantic CSS variables / Tailwind <code>dark:</code> variants on Web and <code>useTheme()</code> semantic tokens on Mobile verified across Light and Dark modes.</li></ul></li><li><strong>Observability &amp; Audit Correlation:</strong><ul><li>Propagates <code>X-Request-Id</code> from <code>brandhub-api-gateway</code> into <code>ApiResponse.requestId</code> and structured backend logs / <code>audit_logs</code> where security-sensitive mutations occur.</li></ul></li><li><strong>BA &amp; Module Traceability:</strong> <a href="./../../../../ba/05-content-task-workflow.html">BA Domain Spec</a> · <a href="./../../../../ba/README.html">BA Overview</a> · <a href="./../../../modules/README.html">Module Specs Index</a>.</li></ul>',17)])])}const h=t(d,[["render",c]]);export{g as __pageData,h as default};
